--

LOCK TABLES `wp_mailpoet_newsletters` WRITE;
/*!40000 ALTER TABLE `wp_mailpoet_newsletters` DISABLE KEYS */;
/*!40000 ALTER TABLE `wp_mailpoet_newsletters` ENABLE KEYS */;
