INSERT INTO `wp_postmeta` VALUES (2,3,'_wp_page_template','default'),(3,6,'_elementor_edit_mode','builder'),(4,6,'_elementor_template_type','kit'),(5,7,'_form','<label> Your name\n    [text* your-name autocomplete:name] </label>\n\n<label> Your email\n    [email* your-email autocomplete:email] </label>\n\n<label> Subject\n    [text* your-subject] </label>\n\n<label> Your message (optional)\n    [textarea your-message] </label>\n\n[submit \"Submit\"]'),(6,7,'_mail','a:8:{s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:41:\"[_site_title] <aschwanden.joel@gmail.com>\";s:4:\"body\";s:191:\"From: [your-name] [your-email]\nSubject: [your-subject]\n\nMessage Body:\n[your-message]\n\n-- \nThis is a notification that a contact form was submitted on your website ([_site_title] [_site_url]).\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";i:0;s:13:\"exclude_blank\";i:0;}'),(7,7,'_mail_2','a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:41:\"[_site_title] <aschwanden.joel@gmail.com>\";s:4:\"body\";s:220:\"Message Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:9:\"recipient\";s:12:\"[your-email]\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";i:0;s:13:\"exclude_blank\";i:0;}'),(8,7,'_messages','a:12:{s:12:\"mail_sent_ok\";s:45:\"Thank you for your message. It has been sent.\";s:12:\"mail_sent_ng\";s:71:\"There was an error trying to send your message. Please try again later.\";s:16:\"validation_error\";s:61:\"One or more fields have an error. Please check and try again.\";s:4:\"spam\";s:71:\"There was an error trying to send your message. Please try again later.\";s:12:\"accept_terms\";s:69:\"You must accept the terms and conditions before sending your message.\";s:16:\"invalid_required\";s:27:\"Please fill out this field.\";s:16:\"invalid_too_long\";s:32:\"This field has a too long input.\";s:17:\"invalid_too_short\";s:33:\"This field has a too short input.\";s:13:\"upload_failed\";s:46:\"There was an unknown error uploading the file.\";s:24:\"upload_file_type_invalid\";s:49:\"You are not allowed to upload files of this type.\";s:21:\"upload_file_too_large\";s:31:\"The uploaded file is too large.\";s:23:\"upload_failed_php_error\";s:38:\"There was an error uploading the file.\";}'),(9,7,'_additional_settings',''),(10,7,'_locale','de_CH'),(11,7,'_hash','2cb0af6574f438c2696f0252eb157bddea0d4310959d433ef460f7f29017e993'),(12,8,'_elementor_edit_mode','builder'),(13,8,'_elementor_template_type','kit'),(14,6,'_wp_page_template','default'),(15,6,'_elementor_page_settings','a:2:{s:9:\"site_name\";s:13:\"FC Schattdorf\";s:16:\"site_description\";s:37:\"Seit 1933 für unsere Zukunft am Ball\";}'),(302,126,'_pingme','1'),(303,126,'_encloseme','1'),(304,127,'_pingme','1'),(305,127,'_encloseme','1'),(306,129,'_EventOrigin','events-calendar'),(307,129,'_tribe_modified_fields','a:1:{s:12:\"_EventOrigin\";i:1782342676;}'),(308,131,'_wp_attached_file','2026/06/fcs-logo.png'),(309,131,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:300;s:6:\"height\";i:80;s:4:\"file\";s:20:\"2026/06/fcs-logo.png\";s:8:\"filesize\";i:1284;s:5:\"sizes\";a:3:{s:9:\"thumbnail\";a:5:{s:4:\"file\";s:19:\"fcs-logo-150x80.png\";s:5:\"width\";i:150;s:6:\"height\";i:80;s:9:\"mime-type\";s:9:\"image/png\";s:8:\"filesize\";i:267;}s:20:\"sportspress-fit-icon\";a:5:{s:4:\"file\";s:19:\"fcs-logo-128x34.png\";s:5:\"width\";i:128;s:6:\"height\";i:34;s:9:\"mime-type\";s:9:\"image/png\";s:8:\"filesize\";i:2273;}s:20:\"sportspress-fit-mini\";a:5:{s:4:\"file\";s:17:\"fcs-logo-32x9.png\";s:5:\"width\";i:32;s:6:\"height\";i:9;s:9:\"mime-type\";s:9:\"image/png\";s:8:\"filesize\