-outline\",\"style\":{\"color\":{\"text\":\"#ffffff\"},\"border\":{\"color\":\"#ffffff\",\"width\":\"2px\"}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/kontakt\" style=\"color:#fff;border-color:#fff;border-width:2px\">Kontakt</a></div>\n<!-- /wp:button -->\n</div>\n<!-- /wp:buttons -->\n\n</div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#f4f4f4\"},\"spacing\":{\"padding\":{\"top\":\"48px\",\"bottom\":\"48px\"}}}} -->\n<div class=\"wp-block-group\" style=\"background-color:#f4f4f4;padding-top:48px;padding-bottom:48px\">\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#c8102e\"},\"typography\":{\"fontSize\":\"11px\",\"fontWeight\":\"700\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"3px\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"color:#c8102e;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:3px\">Der Verein in Zahlen</h2>\n<!-- /wp:heading -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"24px\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-top:24px;max-width:800px;margin:0 auto\">\n<!-- wp:column {\"style\":{\"border\":{\"top\":{\"color\":\"#c8102e\",\"width\":\"3px\"}},\"spacing\":{\"padding\":{\"top\":\"24px\",\"right\":\"16px\",\"bottom\":\"16px\",\"left\":\"16px\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-column\" style=\"border-top:3px solid #c8102e;padding:24px 16px;background:#fff\">\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#c8102e\"},\"typography\":{\"fontSize\":\"2.8rem\",\"fontWeight\":\"900\"}}} --><h2 class=\"wp-block-heading has-text-align-center\" style=\"color:#c8102e;font-size:2.8rem;font-weight:900\">1933</h2><!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"12px\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"2px\"},\"color\":{\"text\":\"#666\"}}} --><p class=\"has-text-align-center\" style=\"color:#666;font-size:12px;text-transform:uppercase;letter-spacing:2px\">Gegründet</p><!-- /wp:paragraph -->\n</div><!-- /wp:column -->\n<!-- wp:column {\"style\":{\"border\":{\"top\":{\"color\":\"#c8102e\",\"width\":\"3px\"}},\"spacing\":{\"padding\":{\"top\":\"24px\",\"right\":\"16px\",\"bottom\":\"16px\",\"left\":\"16px\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-column\" style=\"border-top:3px solid #c8102e;padding:24px 16px;background:#fff\">\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#c8102e\"},\"typography\":{\"fontSize\":\"2.8rem\",\"fontWeight\":\"900\"}}} --><h2 class=\"wp-block-heading has-text-align-center\" style=\"color:#c8102e;font-size:2.8rem;font-weight:900\">600+</h2><!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"12px\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"2px\"},\"color\":{\"text\":\"#666\"}}} --><p class=\"has-text-align-center\" style=\"color:#666;font-size:12px;text-transform:uppercase;letter-spacing:2px\">Mitglieder</p><!-- /wp:paragraph -->\n</div><!-- /wp:column -->\n<!-- wp:column {\"style\":{\"border\":{\"top\":{\"color\":\"#c8102e\",\"width\":\"3px\"}},\"spacing\":{\"padding\":{\"top\":\"24px\",\"right\":\"16px\",\"bottom\":\"16px\",\"left\":\"16px\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-column\" style=\"border-top:3px solid #c8102e;padding:24px 16px;background:#fff\">\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#c8102e\"},\"typography\":{\"fontSize\":\"2.8rem\",\"fontWeight\":\"900\"}}} --><h2 class=\"wp-block-heading has-text-align-center\" style=\"color:#c8102e;font-size:2.8rem;font-weight:900\">21</h2><!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"12px\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"2px\"},\"color\":{\"text\":\"#666\"}}} --><p class=\"has-text-align-center\" style=\"color:#666;font-size:12px;text-transform:uppercase;letter-spacing:2px\">Teams</p><!-- /wp:paragraph -->\n</div><!-- /wp:column -->\n<!-- wp:column {\"style\":{\"border\":{\"top\":{\"color\":\"#c8102e\",\"width\":\"3px\"}},\"spacing\":{\"padding\":{\"top\":\"24px\",\"right\":\"16px\",\"bottom\":\"16px\",\"left\":\"16px\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-column\" style=\"border-top:3px solid #c8102e;padding:24px 16px;background:#fff\">\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#c8102e\"},\"typography\":{\"fontSize\":\"2.8rem\",\"fontWeight\":\"900\"}}} --><h2 class=\"wp-block-heading has-text-align-center\" style=\"color:#c8102e;font-size:2.8rem;font-weight:900\">Uri</h2><!-- /wp:heading -->\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"12px\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"2px\"},\"color\":{\"text\":\"#666\"}}} --><p class=\"has-text-align-center\" style=\"color:#666;font-size:12px;text-transform:uppercase;letter-spacing:2px\">Kanton</p><!-- /wp:paragraph -->\n</div><!-- /wp:column -->\n</div><!-- /wp:columns -->\n</div><!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"48px\",\"bottom\":\"48px\"}},\"color\":{\"background\":\"#ffffff\"}}} -->\n<div class=\"wp-block-group\" style=\"background:#fff;padding:48px 20px\">\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"color\":{\"text\":\"#c8102e\"},\"typography\":{\"fontSize\":\"11px\",\"fontWeight\":\"700\",\"textTransform\":\"uppercase\",\"letterSpacing\":\"3px\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"color:#c8102e;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:3px\">Aktuelles</h2>\n<!-- /wp:heading -->\n<!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"typography\":{\"fontSize\":\"1.8rem\",\"fontWeight